Node* removeDuplicates(Node* head)
{
    int dupli = head->data;
    Node* curr = head->next;

    while (curr) {
        while (curr && curr->data == dupli) {
            if (curr->next)
                curr->next->prev = curr->prev;
            curr->prev->next = curr->next;
            curr = curr->next;
        }
        if (curr) {
            dupli = curr->data;
            curr = curr->next;
        }
    }
    return head;
}

